alter table public.manager_tasks add column waiting_reason text not null default '' check(char_length(waiting_reason)<=300); alter table public.manager_tasks drop constraint manager_tasks_status_check; alter table public.manager_tasks add constraint manager_tasks_status_check check(status in ('open','in_progress','waiting','done','cancelled')); alter table public.manager_tasks add constraint manager_tasks_needs_waiting_reason_check check(status <> 'waiting' or length(trim(waiting_reason))>0);
